{
  "schemaVersion": 1,
  "id": "online-course",
  "version": "1.0.0",
  "kind": "template",
  "name": "Online Course",
  "description": "A practical, project-based course for designers ready to sharpen their craft.",
  "tags": ["industry", "product", "studio-academy"],
  "files": ["registry/templates/online-course.json", "lib/template-renderer.tsx"],
  "dependencies": [
    "class-variance-authority",
    "clsx",
    "lucide-react",
    "motion",
    "radix-ui",
    "react",
    "tailwind-merge",
    "zod"
  ],
  "category": "industry",
  "defaultStyleId": "bento-modern",
  "defaultThemeId": "royal-purple",
  "defaultMotionId": "premium-smooth",
  "defaultMode": "light",
  "compatibleStyles": [
    "modern-minimal",
    "corporate-enterprise",
    "glassmorphism",
    "neo-brutalism",
    "luxury-premium",
    "editorial-magazine",
    "swiss-grid",
    "soft-ui",
    "dark-cinematic",
    "cyberpunk",
    "retro-arcade",
    "playful-friendly",
    "organic-natural",
    "gradient-tech",
    "monochrome",
    "bento-modern",
    "industrial",
    "warm-human",
    "futuristic-spatial",
    "creative-expressive"
  ],
  "supportedThemes": [
    "ocean-blue",
    "royal-purple",
    "emerald",
    "sunset-orange",
    "ruby-red",
    "rose",
    "violet",
    "midnight",
    "slate-neutral",
    "warm-sand",
    "forest",
    "teal",
    "indigo",
    "sky",
    "lavender",
    "citrus",
    "coral",
    "coffee",
    "luxury-gold",
    "monochrome-dark",
    "aurora",
    "cyberpunk-neon",
    "pastel",
    "enterprise-neutral"
  ],
  "supportedMotion": [
    "no-motion",
    "subtle",
    "premium-smooth",
    "spring-interactive",
    "energetic",
    "editorial",
    "stagger-reveal",
    "fade-reveal",
    "slide-reveal",
    "scale-reveal",
    "parallax-light",
    "cinematic",
    "futuristic",
    "playful",
    "dashboard-fast",
    "luxury-slow"
  ],
  "components": ["ui-button", "ui-card"],
  "sections": [
    {
      "id": "navbar-floating",
      "key": "navbar-floating",
      "content": {
        "eyebrow": "Navbar",
        "title": "Studio Academy",
        "href": "#content-course",
        "items": [
          {
            "title": "A clear starting point",
            "description": "Everything you need, thoughtfully organized."
          },
          {
            "title": "Built around your day",
            "description": "Flexible tools that adapt to the way you work."
          },
          {
            "title": "Room to grow",
            "description": "Start simply. Add more when you need it."
          },
          {
            "title": "People first",
            "description": "Accessible, intuitive experiences for everyone."
          }
        ]
      }
    },
    {
      "id": "hero-product",
      "key": "hero-product",
      "content": {
        "eyebrow": "Studio Academy",
        "title": "Learn to design with intention.",
        "description": "A practical, project-based course for designers ready to sharpen their craft.",
        "action": "Explore Studio Academy",
        "href": "#content-course",
        "items": [
          {
            "title": "A clear starting point",
            "description": "Everything you need, thoughtfully organized."
          },
          {
            "title": "Built around your day",
            "description": "Flexible tools that adapt to the way you work."
          },
          {
            "title": "Room to grow",
            "description": "Start simply. Add more when you need it."
          },
          {
            "title": "People first",
            "description": "Accessible, intuitive experiences for everyone."
          }
        ],
        "image": "/images/art.jpg"
      }
    },
    {
      "id": "content-course",
      "key": "content-course",
      "content": {
        "eyebrow": "Course",
        "title": "Your learning journey",
        "href": "#content-course",
        "items": [
          {
            "title": "01 · Start with the right questions",
            "description": "Research methods and a clear project brief."
          },
          {
            "title": "02 · Build a strong foundation",
            "description": "Structure, hierarchy, and design systems."
          },
          {
            "title": "03 · Bring your ideas to life",
            "description": "Prototyping, iteration, and thoughtful details."
          },
          {
            "title": "04 · Share your work",
            "description": "Present your process with clarity and confidence."
          }
        ]
      }
    },
    {
      "id": "content-team",
      "key": "content-team",
      "content": {
        "eyebrow": "Team",
        "title": "Good people. Shared purpose.",
        "href": "#content-course",
        "items": [
          {
            "title": "Morgan Ellis",
            "description": "Founder & creative director"
          },
          {
            "title": "Jordan Lee",
            "description": "Strategy & operations"
          },
          {
            "title": "Sam Rivera",
            "description": "Design & experience"
          },
          {
            "title": "Taylor Reed",
            "description": "Community & partnerships"
          }
        ]
      }
    },
    {
      "id": "testimonials-rating",
      "key": "testimonials-rating",
      "content": {
        "eyebrow": "Testimonials",
        "title": "In good company",
        "href": "#content-course",
        "items": [
          {
            "title": "Thoughtful from the first detail.",
            "description": "We found the clarity we had been looking for. The whole experience felt considered and easy. — Jamie Parker, Studio North"
          },
          {
            "title": "A real difference in our day.",
            "description": "Our team spends less time coordinating and more time doing work we care about. — Alex Kim, Forma"
          },
          {
            "title": "Simple in the best way.",
            "description": "It does what we need beautifully, without getting in the way. — Morgan Reed, Fieldwork"
          }
        ]
      }
    },
    {
      "id": "pricing-single",
      "key": "pricing-single",
      "content": {
        "eyebrow": "Pricing",
        "title": "Choose what works for you",
        "href": "#content-course",
        "items": [
          {
            "title": "Starter",
            "description": "For individuals getting started"
          },
          {
            "title": "Team",
            "description": "For growing teams doing more"
          },
          {
            "title": "Scale",
            "description": "For organizations with bigger ambitions"
          }
        ]
      }
    },
    {
      "id": "faq-numbered",
      "key": "faq-numbered",
      "content": {
        "eyebrow": "Faq",
        "title": "A few things you might be wondering",
        "href": "#content-course",
        "items": [
          {
            "title": "How do I get started?",
            "description": "Choose the option that suits you and follow the guided steps. You can explore the demo before making a decision."
          },
          {
            "title": "Can I change my selection later?",
            "description": "Yes. Your needs can change, and the experience is designed to grow with you."
          },
          {
            "title": "Is support available?",
            "description": "The sample support form demonstrates the flow locally. Connect your own support service for production."
          },
          {
            "title": "What is included?",
            "description": "All listed features are included in the selected option. Review the comparison for details."
          }
        ]
      }
    },
    {
      "id": "content-contact",
      "key": "content-contact",
      "content": {
        "eyebrow": "LET’S CONNECT",
        "title": "Start a conversation.",
        "description": "Tell us a little about what you have in mind.",
        "items": []
      }
    },
    {
      "id": "footer-mega",
      "key": "footer-mega",
      "content": {
        "eyebrow": "Footer",
        "title": "Studio Academy",
        "href": "#content-course",
        "items": [
          {
            "title": "A clear starting point",
            "description": "Everything you need, thoughtfully organized."
          },
          {
            "title": "Built around your day",
            "description": "Flexible tools that adapt to the way you work."
          },
          {
            "title": "Room to grow",
            "description": "Start simply. Add more when you need it."
          },
          {
            "title": "People first",
            "description": "Accessible, intuitive experiences for everyone."
          }
        ]
      }
    }
  ],
  "responsive": true,
  "accessible": true
}
